    "content": "안녕하세요~하준이 얼굴 상처를 보니 아팠겠어요. 주말을 보내고 와 엄마생각이 더 낫는지 울음도 보이고 졸려하는 모습이었어요. 선생님 품에 안겨 창밖을 보다 지나가는 강아지 보며 잠깐 울음을 멈추고 가을열매 밤에도 관심을 보였다  또다시 울기를 반복하는 모습이었습니다.\n\n내일은 9시 30분~11시 30분까지 2시간 적응시간을 갖겠습니다. 하준이 컨디션보고 하원시간 조절해 할머님께 연락드리겠습니다.",
