    "weather": "sunny",
    "content": "* 오늘 '아빠의 날'로 하늘반 민지우 아버님께서 오셔서 함께 고구마와 무(빨간무, 사과무)를 수확 해보았습니다.(바다,하늘반)\n8일 금요일 오후 3시부터 해늘 부모님들께 수확한 작물을 무인 판매하니(1인 1바구니) 많은 관심과 협조 부탁드립니다.",
