    "weather": "sunny",
    "content": "안녕하세요~~ 하준이 모양 끼우기에 관심을 보이며 선생님의 도움을 받아 모양을 맞춰보았어요. 활동량이 많아 여러 영역을 자유롭게 탐색하며 놀이하였는데 자리에 앉아 집중하며 모양을 끼워보려 여러 번 시도하는 모습 보였습니다.\n\n일과 중 하준이의 상태를 지켜보았는데 땀이 나거나 더워하는 모습이 관찰되지 않아 민소매를 벗기지 않고 유지했습니다.",
