      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0090_2024-11-28_1140682631_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0090_2024-11-28_1140682631_03.jpg"
