      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0104_2025-01-02_1156554873_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0104_2025-01-02_1156554873_03.jpg"
