      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0105_2025-01-08_1158723270_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0105_2025-01-08_1158723270_03.jpg"
