    "weather": "mostly_cloudy",
    "content": "주말지내고 온 바다반 친구들은 새롭게 지원해준 동물 사운드북과 와플블록에 관심보였습니다. 커다란 박스에 스티커를 붙이고 색연필로 끼적이기 해서 꾸며보았고, 안에 들어가고 싶다고 표현하여 박스기차를 만들어 친구들과 함께 타보기도 했답니다.",
