    "class_name": "바다2",
    "weather": "snow",
    "content": "놀이시간에 폼블록을 활용해 미끄럼틀 경사를 만들어 자동차를 굴려보고, 와플블록을 꽂아서 올려놓고 생일축하노래를 함께 부르며 \"후~\"하고 촛불을 끄는 친구들입니다. 풍선을 불어주니 흔들고 던지며 몸을 움직이고, 스티커를 붙였다 뗐다 집중하는 모습이었습니다.\n*가족사진을 알림장으로 한장씩 보내주세요~^^\n*하준이 여벌옷 상하의 보내주세요.",
