    "content": "오늘은 자동차도로 스펀지퍼즐을 끼워 연결하고 그 위를 걸어보기도 하고 자동차를 굴려보기도 하였습니다. 퍼즐을 끼우다가 얼굴을 가리고 \"까꿍~\"놀이로 이어가는 친구들입니다.^^ 박스종이에 여러가지모양 스티커 붙이기에 집중하고, 유희실에서 얼룩말을 신나게 타는 모습이었습니다.",
