    "class_name": "바다2",
    "weather": "overcast",
    "content": "오전에 영유아 대상으로 한 [스마트폰 과의존 예방교육]이 진행되었습니다. 약속시간만큼만 사용하고 밥 먹을때 사용하지 않기, 바른자세로 사용하기, 스마트폰대신 재미있는 놀이하기 등 올바른 스마트폰사용 방법들에 대해서 알아보았습니다. 교육 후 교실에서 자유롭게 놀이하며  블록놀이, 보자기로 까꿍놀이, 책읽기에 집중하는 모습이었습니다.",
