      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0217_2025-07-22_1252304282_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0217_2025-07-22_1252304282_03.jpg",
