    "weather": "overcast",
    "content": "오늘은 옥상 텃밭에서 시원한 물놀이 시간이 있었습니다. 물풍선 놀이와 물총놀이까지 너무 신나는 하루였습니다. ^^ 신나게 놀아서인지 오늘은 점심도 맛있게 잘 먹었습니다.",
