      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0299_2025-11-26_1312462606_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0299_2025-11-26_1312462606_03.jpg",
