    "content": "안녕하세요 원에서는 코피가 나지는 않았습니다.\n코를 후비는 행동도 거의 보이지 않았으나 입술을 손으로 뜯으려고 하는 모습이 보여 립밤을 수시로 발라주었습니다.",
