      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0445_2026-11-02_1475124693_02.jpg",
      "C:\\Users\\GS\\kidsnote-pdf\\album_assets\\images\\0445_2026-11-02_1475124693_03.jpg"
